async function main(ctx) {
  const resp = ctx.lastOutputOf('get_metadata') || {};

  if (!resp.body) {
    throw new Error('No response body from Google Sheets API');
  }

  return {
    success: true,
    spreadsheetId: resp.body.spreadsheetId,
    spreadsheetUrl: resp.body.spreadsheetUrl,
    properties: resp.body.properties,
    sheets: resp.body.sheets?.map(s => ({
      sheetId: s.properties.sheetId,
      title: s.properties.title,
      index: s.properties.index,
      gridProperties: s.properties.gridProperties,
      data: s.data || undefined
    })) || [],
    namedRanges: resp.body.namedRanges || [],
    developerMetadata: resp.body.developerMetadata || []
  };
}
